import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, issueInvoice, invoiceTotals } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';
import { createCreditNote } from '../src/credits.js';

test('createCreditNote returns credit note object', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const invoice = r1.value;
  const r2 = issueInvoice(invoice, []);
  const issued = r2.value;

  const r3 = createCreditNote(issued, { amount: 1000, reason: 'Return', date: '2025-10-15' }, []);
  assert.equal(r3.ok, true);
  assert.equal(r3.value.number, 'CN-2025-0001');
  assert.equal(r3.value.invoiceNumber, 'INV-2025-0001');
  assert.equal(r3.value.customerId, 'C-001');
  assert.equal(r3.value.amount, 1000);
  assert.equal(r3.value.reason, 'Return');
  assert.equal(r3.value.date, '2025-10-15');
});

test('createCreditNote rejects draft invoices', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const invoice = r1.value;

  const r2 = createCreditNote(invoice, { amount: 1000, reason: 'Return', date: '2025-10-15' }, []);
  assert.equal(r2.ok, false);
  assert.equal(r2.error, 'NOT_ISSUED');
});

test('createCreditNote rejects non-integer amounts', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const invoice = r1.value;
  const r2 = issueInvoice(invoice, []);
  const issued = r2.value;

  const r3 = createCreditNote(issued, { amount: 1000.5, reason: 'Return', date: '2025-10-15' }, []);
  assert.equal(r3.ok, false);
  assert.equal(r3.error, 'AMOUNT_INVALID');
});

test('createCreditNote rejects zero amount', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const invoice = r1.value;
  const r2 = issueInvoice(invoice, []);
  const issued = r2.value;

  const r3 = createCreditNote(issued, { amount: 0, reason: 'Return', date: '2025-10-15' }, []);
  assert.equal(r3.ok, false);
  assert.equal(r3.error, 'AMOUNT_INVALID');
});

test('createCreditNote rejects negative amounts', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const invoice = r1.value;
  const r2 = issueInvoice(invoice, []);
  const issued = r2.value;

  const r3 = createCreditNote(issued, { amount: -1000, reason: 'Return', date: '2025-10-15' }, []);
  assert.equal(r3.ok, false);
  assert.equal(r3.error, 'AMOUNT_INVALID');
});

test('createCreditNote rejects credit amount exceeding invoice total', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const invoice = r1.value;
  const r2 = issueInvoice(invoice, []);
  const issued = r2.value;
  const totals = invoiceTotals(issued);

  const r3 = createCreditNote(issued, { amount: totals.total + 1, reason: 'Return', date: '2025-10-15' }, []);
  assert.equal(r3.ok, false);
  assert.equal(r3.error, 'CREDIT_TOO_HIGH');
});

test('createCreditNote accepts credit equal to invoice total', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const invoice = r1.value;
  const r2 = issueInvoice(invoice, []);
  const issued = r2.value;
  const totals = invoiceTotals(issued);

  const r3 = createCreditNote(issued, { amount: totals.total, reason: 'Full return', date: '2025-10-15' }, []);
  assert.equal(r3.ok, true);
  assert.equal(r3.value.amount, totals.total);
});

test('createCreditNote works on partially_paid invoices', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const invoice = r1.value;
  const r2 = issueInvoice(invoice, []);
  const issued = r2.value;
  const totals = invoiceTotals(issued);
  const half = Math.floor(totals.total / 2);

  const r3 = recordPayment(issued, { amount: half, date: '2025-10-08' });
  const partially = r3.value;

  const r4 = createCreditNote(partially, { amount: 500, reason: 'Adjustment', date: '2025-10-15' }, []);
  assert.equal(r4.ok, true);
  assert.equal(r4.value.number, 'CN-2025-0001');
});

test('createCreditNote works on paid invoices', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const invoice = r1.value;
  const r2 = issueInvoice(invoice, []);
  const issued = r2.value;
  const totals = invoiceTotals(issued);

  const r3 = recordPayment(issued, { amount: totals.total, date: '2025-10-08' });
  const paid = r3.value;

  const r4 = createCreditNote(paid, { amount: 1000, reason: 'Refund', date: '2025-10-15' }, []);
  assert.equal(r4.ok, true);
  assert.equal(r4.value.number, 'CN-2025-0001');
});

test('createCreditNote numbers credit notes separately from invoices', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const invoice = r1.value;
  const r2 = issueInvoice(invoice, ['INV-2025-0001', 'INV-2025-0002']);
  const issued = r2.value;

  const r3 = createCreditNote(issued, { amount: 500, reason: 'Adjustment', date: '2025-10-15' }, ['INV-2025-0001', 'INV-2025-0002']);
  assert.equal(r3.ok, true);
  assert.equal(r3.value.number, 'CN-2025-0001');
});

test('createCreditNote increments credit note counter', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const invoice = r1.value;
  const r2 = issueInvoice(invoice, []);
  const issued = r2.value;

  const r3 = createCreditNote(issued, { amount: 500, reason: 'First', date: '2025-10-15' }, []);
  assert.equal(r3.value.number, 'CN-2025-0001');

  const r4 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-10',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const invoice2 = r4.value;
  const r5 = issueInvoice(invoice2, ['INV-2025-0001']);
  const issued2 = r5.value;

  const r6 = createCreditNote(issued2, { amount: 500, reason: 'Second', date: '2025-10-15' }, ['CN-2025-0001', 'INV-2025-0001']);
  assert.equal(r6.value.number, 'CN-2025-0002');
});

test('createCreditNote handles different years separately', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const invoice = r1.value;
  const r2 = issueInvoice(invoice, []);
  const issued = r2.value;

  const r3 = createCreditNote(issued, { amount: 500, reason: 'Return', date: '2026-01-15' }, []);
  assert.equal(r3.ok, true);
  assert.equal(r3.value.number, 'CN-2026-0001');
});

test('createCreditNote uses correct year from date', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const invoice = r1.value;
  const r2 = issueInvoice(invoice, []);
  const issued = r2.value;

  const r3 = createCreditNote(issued, { amount: 500, reason: 'Return', date: '2024-01-15' }, []);
  assert.equal(r3.ok, true);
  assert.equal(r3.value.number, 'CN-2024-0001');
});

test('createCreditNote pads counter to 4 digits', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const invoice = r1.value;
  const r2 = issueInvoice(invoice, []);
  const issued = r2.value;

  const existingNumbers = [];
  for (let i = 1; i < 1000; i++) {
    existingNumbers.push(`CN-2025-${String(i).padStart(4, '0')}`);
  }

  const r3 = createCreditNote(issued, { amount: 500, reason: 'Return', date: '2025-10-15' }, existingNumbers);
  assert.equal(r3.ok, true);
  assert.equal(r3.value.number, 'CN-2025-1000');
});

test('createCreditNote with high credit number', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const invoice = r1.value;
  const r2 = issueInvoice(invoice, []);
  const issued = r2.value;

  const existingNumbers = [
    'CN-2025-9999',
    'INV-2025-0001',
    'INV-2025-0002',
  ];

  const r3 = createCreditNote(issued, { amount: 500, reason: 'Return', date: '2025-10-15' }, existingNumbers);
  assert.equal(r3.ok, true);
  assert.equal(r3.value.number, 'CN-2025-10000');
});

test('createCreditNote preserves invoice number', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const invoice = r1.value;
  const r2 = issueInvoice(invoice, ['INV-2025-0099']);
  const issued = r2.value;

  const r3 = createCreditNote(issued, { amount: 500, reason: 'Return', date: '2025-10-15' }, ['INV-2025-0099']);
  assert.equal(r3.value.invoiceNumber, 'INV-2025-0100');
});

test('createCreditNote preserves customer ID', () => {
  const r1 = createInvoice({
    customerId: 'C-003',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const invoice = r1.value;
  const r2 = issueInvoice(invoice, []);
  const issued = r2.value;

  const r3 = createCreditNote(issued, { amount: 500, reason: 'Return', date: '2025-10-15' }, []);
  assert.equal(r3.value.customerId, 'C-003');
});

test('createCreditNote with discount and VAT applied', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2, discountPercent: 10 }],
  });
  const invoice = r1.value;
  const r2 = issueInvoice(invoice, []);
  const issued = r2.value;
  const totals = invoiceTotals(issued);

  const r3 = createCreditNote(issued, { amount: 1000, reason: 'Partial refund', date: '2025-10-15' }, []);
  assert.equal(r3.ok, true);
  assert.ok(r3.value.amount <= totals.total);
});

test('createCreditNote with multiple existing credits in same year', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const invoice = r1.value;
  const r2 = issueInvoice(invoice, []);
  const issued = r2.value;

  const existingNumbers = [
    'CN-2025-0001',
    'CN-2025-0002',
    'CN-2025-0003',
    'CN-2024-0001',
    'CN-2026-0001',
  ];

  const r3 = createCreditNote(issued, { amount: 500, reason: 'Return', date: '2025-10-15' }, existingNumbers);
  assert.equal(r3.ok, true);
  assert.equal(r3.value.number, 'CN-2025-0004');
});

